window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f9f61d9fb691543d"]={"versions": [{"id": "FIG-f9f61d9fb691543d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 (Software & Systems Process Engineering Metamodel) Aktivitäts- bzw. Workflow-Diagramm im Kontext der AUTOSAR Methodology (AUTOSAR_TR_Methodology). Das Diagramm visualisiert die prozessuale Einbettung des Arbeitsschritts zur Festlegung der Signal-Fan-out-Konfiguration innerhalb des AUTOSAR System- und Kommunikationsdesigns (System Template / Interaction Layer).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen / Akteure:</strong></li>\n<li><code>System Engineer</code> (Kardinalität <code>1</code>): Ausführende Rolle im Systementwicklungsprozess; verknüpft über die gerichtete Assoziation <code>«performs»</code>.</li>\n<li><strong>Aktivitäten / Tasks:</strong></li>\n<li><code>Define RTE Fan-out</code>: Methodischer Prozessschritt zur Spezifikation und Konfiguration des RTE-/Kommunikations-Fan-outs für Signale, die an mehrere Empfänger verteilt werden.</li>\n<li><strong>Artefakte / Work Products:</strong></li>\n<li><code>System Signal</code> (Kardinalität <code>1..*</code>, Stereotyp <code>«input»</code>): Eingangsdaten der Systembeschreibung; mindestens ein oder mehrere logische Systemsignale, die der Fan-out-Verteilung unterliegen.</li>\n<li><code>Interaction Layer</code> (Kardinalität <code>1</code>, Stereotyp <code>«output»</code>): Ausgangsartefakt; die resultierende Konfiguration bzw. Beschreibung der Interaktionsschicht (COM/Interaction Layer bzw. ISignal-Routing).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>System Engineer</code> initiiert den Arbeitsschritt <code>Define RTE Fan-out</code>.</li>\n<li>Als Eingabe werden ein oder mehrere definierte System-Signale (<code>System Signal</code>, Multiplizität <code>1..*</code>) aus der Systembeschreibung bereitgestellt.</li>\n<li>Im Prozessschritt <code>Define RTE Fan-out</code> werden die 1:n-Signalpfade modelliert und die Abbildung der Signale auf die entsprechenden Zielstrukturen der Interaktionsschicht definiert.</li>\n<li>Als Prozessergebnis entsteht genau ein konsistentes Artefakt der Interaktionsschicht (<code>Interaction Layer</code>, Multiplizität <code>1</code>), welches die nachgelagerte Generierung von RTE und COM-Stack steuert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Richtlinie zur Sicherstellung einer standardkonformen Konfiguration von 1:n-Kommunikationsbeziehungen. Die Definition des RTE Fan-out auf Systemebene stellt sicher, dass ein einzelnes System-Signal konsistent auf mehrere ISignals oder Empfänger-Ports abgebildet werden kann. Für Integratoren und Tool-Entwickler ist relevant, dass die Kardinalität der Eingangsartefakte (<code>1..*</code>) strikt eingehalten wird, da die Interaktionsschicht ohne zugrundeliegende System-Signale nicht vollständig abgeleitet werden kann.</p>"}, {"id": "FIG-efb0d546e1d6e5bf", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 (Software & Systems Process Engineering Metamodel) Aktivitäts- bzw. Workflow-Diagramm im Kontext der AUTOSAR Methodology (AUTOSAR_TR_Methodology). Das Diagramm visualisiert die prozessuale Einbettung des Arbeitsschritts zur Festlegung der Signal-Fan-out-Konfiguration innerhalb des AUTOSAR System- und Kommunikationsdesigns (System Template / Interaction Layer).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen / Akteure:</strong></li>\n<li><code>System Engineer</code> (Kardinalität <code>1</code>): Ausführende Rolle im Systementwicklungsprozess; verknüpft über die gerichtete Assoziation <code>«performs»</code>.</li>\n<li><strong>Aktivitäten / Tasks:</strong></li>\n<li><code>Define RTE Fan-out</code>: Methodischer Prozessschritt zur Spezifikation und Konfiguration des RTE-/Kommunikations-Fan-outs für Signale, die an mehrere Empfänger verteilt werden.</li>\n<li><strong>Artefakte / Work Products:</strong></li>\n<li><code>System Signal</code> (Kardinalität <code>1..*</code>, Stereotyp <code>«input»</code>): Eingangsdaten der Systembeschreibung; mindestens ein oder mehrere logische Systemsignale, die der Fan-out-Verteilung unterliegen.</li>\n<li><code>Interaction Layer</code> (Kardinalität <code>1</code>, Stereotyp <code>«output»</code>): Ausgangsartefakt; die resultierende Konfiguration bzw. Beschreibung der Interaktionsschicht (COM/Interaction Layer bzw. ISignal-Routing).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>System Engineer</code> initiiert den Arbeitsschritt <code>Define RTE Fan-out</code>.</li>\n<li>Als Eingabe werden ein oder mehrere definierte System-Signale (<code>System Signal</code>, Multiplizität <code>1..*</code>) aus der Systembeschreibung bereitgestellt.</li>\n<li>Im Prozessschritt <code>Define RTE Fan-out</code> werden die 1:n-Signalpfade modelliert und die Abbildung der Signale auf die entsprechenden Zielstrukturen der Interaktionsschicht definiert.</li>\n<li>Als Prozessergebnis entsteht genau ein konsistentes Artefakt der Interaktionsschicht (<code>Interaction Layer</code>, Multiplizität <code>1</code>), welches die nachgelagerte Generierung von RTE und COM-Stack steuert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Richtlinie zur Sicherstellung einer standardkonformen Konfiguration von 1:n-Kommunikationsbeziehungen. Die Definition des RTE Fan-out auf Systemebene stellt sicher, dass ein einzelnes System-Signal konsistent auf mehrere ISignals oder Empfänger-Ports abgebildet werden kann. Für Integratoren und Tool-Entwickler ist relevant, dass die Kardinalität der Eingangsartefakte (<code>1..*</code>) strikt eingehalten wird, da die Interaktionsschicht ohne zugrundeliegende System-Signale nicht vollständig abgeleitet werden kann.</p>"}], "trans": [{"from": "FIG-f9f61d9fb691543d", "to": "FIG-efb0d546e1d6e5bf", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
